def simulate_game(n):
    """Simulates the game for small n to test termination."""
    all_numbers = set(range(1, n + 1))
    alice_picks = set()
    bob_picks = set()

    turn = 0 # 0 for Alice, 1 for Bob

    while True:
        current_player_picks = alice_picks if turn == 0 else bob_picks

        # Find possible moves
        possible_moves = set()
        for x in all_numbers - (alice_picks | bob_picks):
            is_valid = True

            # Check constraint (ii) against current player's picks
            for p in current_player_picks:
                if abs(x - p) == 1:
                    is_valid = False
                    break

            if is_valid:
                possible_moves.add(x)

        if not possible_moves:
            # No moves possible
            if len(alice_picks | bob_picks) == n:
                return "Draw"
            else:
                # Current player loses
                return f"Loss (Turn {turn+1})"

        # In a theoretical simulation, we assume optimal play (maximizing final picks).
        # For simplicity and pattern finding, we pick the smallest valid move.
        move = min(possible_moves)

        if turn == 0:
            alice_picks.add(move)
        else:
            bob_picks.add(move)

        all_numbers.discard(move)
        turn = 1 - turn

# Test small N
for i in range(1, 9):
    result = simulate_game(i)
    print(f"N={i}: {result}")
